G("ya", "N5", "〜や", r"K: や/や/助詞-副助詞", "例をいくつか並べる", "「AやB」＝AやBなど、ほかにもあるという並べ方。", "the-particle-%e3%82%84/")
G("kara_from", "N5", "〜から（起点）", r"K: から/から/助詞-格助詞", "〜から始まる（起点）", "時間や場所の始まりを示す。「朝から」「村から」。", "the-particle-%e3%81%8b%e3%82%89/")
G("made", "N5", "〜まで", r"K: まで/まで/助詞-副助詞", "〜まで（終わりの点）", "時間や場所の終わりを示す。「夜まで」「街まで」。", "the-particle-%e3%81%be%e3%81%a7/")
G("dake", "N5", "〜だけ", r"だけ", "〜だけ（限定）", "「それだけ」＝それ以外はない、という限定。", "the-particle-%e3%81%a0%e3%81%91/")
G("shika", "N5", "〜しか〜ない", r"しか.*(ない|ねえ|ません|なかった|ん)", "〜しかない（それだけ）", "しか＋否定で「それだけしかない」と少ないことを強調する。", "shika-hoka/")
