G("toki", "N5", "〜とき", r"(時|とき)(に|は|も|、|の|から|まで|だ|$)", "〜するとき（時）", "何かが起こる時を表す。「子どもの時」「行く時」。", "when-%e6%99%82/")
G("tari", "N5", "〜たり〜たりする", r"(たり|だり)", "いくつかの動作を例として並べる", "いくつかの動作から例をあげる。「食べたり飲んだりする」。", "the-particle-%e3%81%9f%e3%82%8a/")
G("nagara", "N5", "〜ながら", r"K: ながら/ながら/助詞", "二つのことを同時にする", "二つの動作を同時にする。「歩きながら話す」。", "the-particle-%e3%81%aa%e3%81%8c%e3%82%89-i-simultaneous-action/")
G("tsumori", "N5", "〜つもり", r"つもり|積もり", "〜するつもり（予定・意志）", "自分の予定や意志。「行くつもりだ」。", "planning-obligation/")
G("ichiban", "N5", "〜（の中で）一番", r"(一番|いちばん)", "いちばん：最も", "いくつかの中で最も〜。「世界で一番強い」。", "the-superlative/")
G("yori", "N5", "〜より（比較）", r"より", "〜と比べて", "比べる基準を示す。「前より強い」。", "the-particle-%e3%82%88%e3%82%8a/")
G("hougaii", "N5", "〜ほうがいい", r"(方|ほう)が(いい|良い|よかった|ましだ|まし)", "アドバイス：〜したほうがいい", "相手へのアドバイス。「休んだほうがいい」。", "best-that/")
G("nainaihou", "N5", "〜ないほうがいい", r"ない(方|ほう)が(いい|良い)", "〜しないほうがいい", "しないようにアドバイスする。「行かないほうがいい」。", "best-that/")
